def tables():
    """Return explicit tables and their Chinese mapping for the shared formatter."""
    passes={sid:[en for en,zh in rows] for sid,rows in PASS.items()}
    failures={(sid,b,n):{g:pair[0] for g,pair in fs.items()} for sid,paths in FAIL.items() for n,fs in paths.items() for b in ['A','B']}
    translations={en:zh for rows in PASS.values() for en,zh in rows}
    translations.update({en:zh for paths in FAIL.values() for fs in paths.values() for en,zh in fs.values()})
    return passes,failures,translations
